"""Strict input/provenance and pixel-center footprint checks; no geometry edit."""
from continuous_pilot import *


def exact_footprint(master,part,view):
    v=C['views'][view];s=height/v['scale_px_per_unit'];yaw=math.radians(v['yaw_degrees']);x0,y0,x1,y1=v['crop'];out=np.zeros((y1-y0,x1-x0),bool);xx=(np.arange(x0,x1)+.5-v['axis_u'])*s;yy=(v['sole_y']-(np.arange(y0,y1)+.5))*s;ids=[]
    for component in master['components']:
        instances=[i for i in master['instances'] if i['component']==component['id']]
        for inst in instances:
            it=transform(inst.get('transform'))
            for op in component['operations']:
                if op['part']!=part:continue
                assert op['shape']['kind']=='extrusion';verts=np.array([apply(it,q) for q in [p for quad in primitive_quads(op) for p in quad]]);yvals=np.unique(np.round(verts[:,1],12));assert len(yvals)==2,'Pixel-center slab projection needs world-Y prism; unsupported geometry must not silently fall back'
                us=math.cos(yaw)*verts[:,0]-math.sin(yaw)*verts[:,2];xm=(xx>=us.min())&(xx<us.max());ym=(yy>=verts[:,1].min())&(yy<verts[:,1].max());out|=ym[:,None]&xm[None,:];ids.append(op['id'])
    return out,ids


def verify_manifest(meta,source):
    if meta.get('schema')!='riverstone.continuous_pilot.strict_measured_input.v1':raise ValueError('Strict measured input schema required')
    for dep in meta['dependencies']:
        path=REPO/dep['path']
        if not path.is_file() or sha(path)!=dep['sha256']:raise ValueError('Stale/missing input dependency: '+dep['role'])
    actual=hashlib.sha256(np.ascontiguousarray(source).tobytes()).hexdigest()
    if actual!=meta['input_pixels_sha256']:raise ValueError('Source pixel array differs from measured input')
    if meta['source_status']=='approved_original' and actual!=meta['approved_pixels_sha256']:raise ValueError('Mutation cannot inherit approved-original status')
    return True


def run():
    dep_paths={'approved_image':REPO/C['source'],'measurement_contract':ROOT/'data/measurement_contract.json','semantic_annotations':ROOT/'data/violet_full_semantic_annotations_v02.json','frozen_semantic_domains':ROOT/'full_measurement/violet_branches/branch_masks.npz','actual_parent_master':ROOT/'full01/generated/volume_master_v03.json.gz','actual_parent_sections':ROOT/'full01/evidence/volume_fit_v03.json.gz','hidden_depth_priors':BASE/'data/pilot_priors.json','extractor_geometry_adapter':BASE/'tools/continuous_pilot.py','measured_metadata':BASE/'evidence/independent_measurements.json.gz','measured_arrays':BASE/'evidence/independent_masks.npz','compiler':COMMON/'core.py','render_exporter':COMMON/'render_data.py','mesh':REPO/'voxel_character/tools/mesh.py'}
    pixelsha=hashlib.sha256(SOURCE.tobytes()).hexdigest();meta={'schema':'riverstone.continuous_pilot.strict_measured_input.v1','source_status':'approved_original','approved_source_file_sha256':C['source_sha256'],'input_pixels_sha256':pixelsha,'approved_pixels_sha256':pixelsha,'dependencies':[{'role':k,'path':str(p.relative_to(REPO)),'sha256':sha(p)} for k,p in dep_paths.items()],'limitations':['The previous loader validated only source+arrays. This supplemental strict validator binds every listed input; old outputs are retained, not relabeled as generated by this new tool.','Actual pixel mutation variants must record TEST_ONLY and their raw-pixel digest. The earlier in-memory mutation master inherited approved source_sha; its regression digest is a shape-only test result, not an approved asset.','Changing shared side masks or parent sections may affect both pilot parts. Part-locality only applies to mutations confined to a declared front semantic domain.']};write(BASE/'evidence/strict_input_manifest.json',meta)
    checks={'all_dependencies_current':verify_manifest(meta,SOURCE),'stale_dependency_rejected':True}
    for dep in meta['dependencies']:
        bad=copy.deepcopy(meta);next(x for x in bad['dependencies'] if x['role']==dep['role'])['sha256']='0'*64
        try:verify_manifest(bad,SOURCE);checks['stale_dependency_rejected']=False
        except ValueError:pass
    mutated=SOURCE.copy();mutated[0,0]=[1,2,3]
    try:verify_manifest(meta,mutated);checks['wrong_pixel_input_rejected']=False
    except ValueError:checks['wrong_pixel_input_rejected']=True
    corrected={};details={}
    for view in ['front','back']:
        exact,ids=exact_footprint(VOL,'head_cap_closed',view);pil=footprint('head_cap_closed',view);eligible=BM[view+'__eligible__hair_visible'];head=eligible&exact;hair=eligible&~exact;corrected[view+'__head']=head;corrected[view+'__residual']=hair
        details[view]={'eligible':int(eligible.sum()),'head_owned':int(head.sum()),'residual_owned':int(hair.sum()),'missing':int((eligible&~(head|hair)).sum()),'duplicate':int((head&hair).sum()),'Pillow_additional_head_pixels':int((eligible&pil&~exact).sum()),'Pillow_missed_head_pixels':int((eligible&exact&~pil).sum()),'actual_head_operations':len(ids),'pixel_center_convention':'u+0.5,v+0.5 orthographic projection of actual world-Y extrusions; half-open volume bounds'}
    np.savez_compressed(BASE/'evidence/pixel_center_ownership.npz',**corrected);write(BASE/'evidence/pixel_center_ownership_correction.json',{'method_source_sha256':sha(__file__),'parent_master_sha256':sha(dep_paths['actual_parent_master']),'details':details,'status':'Supplemental input correction only; existing02/03 master used Pillow projection and has not been rebuilt with these corrected masks. No retroactive geometry PASS.'});write(BASE/'evidence/strict_input_validation.json',checks);print(json.dumps({'checks':checks,'ownership':details}))
if __name__=='__main__':run()
